  // Filas para la pantalla de inicio
  trending: () => tmdb("/trending/all/week"),
  popularMovies: (page = 1) => tmdb("/movie/popular", { page }),
  topRatedMovies: (page = 1) => tmdb("/movie/top_rated", { page }),
  popularSeries: (page = 1) => tmdb("/tv/popular", { page }),
  topRatedSeries: (page = 1) => tmdb("/tv/top_rated", { page }),
  // Búsqueda
  searchMulti: (query, page = 1) => tmdb("/search/multi", { query, page, include_adult: "false" }),
  trendingMovies: () => tmdb("/trending/movie/week"),
  trendingSeries: () => tmdb("/trending/tv/week"),
  // Descubrir por género
  discoverByGenre: (genreId, type = "movie", page = 1) => tmdb(`/discover/${type}`, {
    with_genres: genreId,
    sort_by: "popularity.desc",
    page,
    "vote_count.gte": 100
  }),
  discoverByGenreSorted: (genreId, type, sortBy) => tmdb(`/discover/${type}`, {
    with_genres: genreId,
    sort_by: sortBy,
    page: 1,
    "vote_count.gte": 50
  }),
  // Descubrir por plataforma (watch provider)
  discoverByProvider: (providerId, type = "movie", region = "US") => tmdb(`/discover/${type}`, {
    with_watch_providers: providerId,
    watch_region: region,
    sort_by: "popularity.desc",
    watch_monetization_types: "flatrate"
  }),
  // Detalle (videos en es+en para maximizar tráilers disponibles)
  movieDetails: (id) => tmdb(`/movie/${id}`, {
    append_to_response: "credits,videos,similar",
    include_video_language: "es,en"
  }),
  tvDetails: (id) => tmdb(`/tv/${id}`, {
    append_to_response: "credits,videos,similar",
    include_video_language: "es,en"
  }),
  tvSeason: (id, season) => tmdb(`/tv/${id}/season/${season}`),
  // Logos (PNG transparente) del título, en varios idiomas
  images: (type, id) => tmdb(`/${type}/${id}/images`, { include_image_language: "es,en,null" }),
  // Persona (actor/director) + su filmografía
  personDetails: (id) => tmdb(`/person/${id}`, { append_to_response: "combined_credits" })
